CREATE TABLE IF NOT EXISTS hooks (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, `name` VARCHAR(64) NOT NULL, pinned_version_id VARCHAR(36) NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT fk_hooks_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE hooks ADD CONSTRAINT hook_team_name UNIQUE (team_id, `name`);
CREATE TABLE IF NOT EXISTS hook_versions (id VARCHAR(36) PRIMARY KEY, hook_id VARCHAR(36) NOT NULL, version VARCHAR(64) COLLATE utf8mb4_bin NOT NULL, digest VARCHAR(71) NOT NULL, events VARCHAR(255) NOT NULL, matcher VARCHAR(256) COLLATE utf8mb4_bin NULL, command VARCHAR(255) NOT NULL, timeout_seconds INT NOT NULL, size_bytes BIGINT NOT NULL, file_count INT NOT NULL, published_by VARCHAR(36) NOT NULL, published_at BIGINT NOT NULL, CONSTRAINT fk_hook_versions_hook_id__id FOREIGN KEY (hook_id) REFERENCES hooks(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE hook_versions ADD CONSTRAINT hook_version_label UNIQUE (hook_id, version);
CREATE TABLE IF NOT EXISTS hook_files (version_id VARCHAR(36), `path` VARCHAR(255), mode VARCHAR(16) NOT NULL, `size` INT NOT NULL, sha256 CHAR(64) NOT NULL, content MEDIUMBLOB NOT NULL, CONSTRAINT pk_hook_files PRIMARY KEY (version_id, `path`), CONSTRAINT fk_hook_files_version_id__id FOREIGN KEY (version_id) REFERENCES hook_versions(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS hook_assignments (id VARCHAR(36) NOT NULL, hook_id VARCHAR(36), member_id VARCHAR(36), decision VARCHAR(8) NULL, updated_by VARCHAR(36) NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT pk_hook_assignments PRIMARY KEY (hook_id, member_id), CONSTRAINT fk_hook_assignments_hook_id__id FOREIGN KEY (hook_id) REFERENCES hooks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_hook_assignments_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE hook_assignments ADD CONSTRAINT hook_assignment_id UNIQUE (id);
CREATE INDEX hook_assignment_member ON hook_assignments (member_id);
